import {
  createBrowserRouter,
  RouterProvider,
  Form,
  useActionData,
  type ActionFunctionArgs,
  type RouteObject,
} from 'react-router';

export async function noteAction({ request }: ActionFunctionArgs): Promise<{ saved: string }> {
  const fd = await request.formData();
  return { saved: String(fd.get('text')) };
}

export function NoteView() {
  const data = useActionData() as { saved: string } | undefined;
  return (
    <>
      <Form method="post">
        <label htmlFor="text">text</label>
        <input id="text" name="text" />
        <button type="submit">save</button>
      </Form>
      {data ? <p>saved: {data.saved}</p> : null}
    </>
  );
}

export const routes: RouteObject[] = [
  { path: '/notes', action: noteAction, element: <NoteView /> },
];

export const router = createBrowserRouter(routes);

export function App() {
  return <RouterProvider router={router} />;
}
